import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    counted = df[df['row_kind'] == 'counted'].copy()
except:
    counted = df.copy()

try:
    non_contractor_types = ['contractor','contingent','agency','agency worker','consultant','freelancer','vendor','contract worker','temp agency']
    counted['Worker_Type_lower'] = counted['Worker_Type'].str.lower()
    staff = counted[~counted['Worker_Type_lower'].isin(non_contractor_types)].copy()
except:
    staff = counted.copy()

metrics = ['FTE', 'Annual_Salary', 'Performance_Rating']

# EDA
try:
    eda = {}
    for col in metrics:
        s = staff[col].dropna()
        eda[col] = {
            "mean": float(s.mean()),
            "std": float(s.std()),
            "min": float(s.min()),
            "max": float(s.max()),
            "median": float(s.median()),
            "count": int(s.count())
        }
    result['eda_summary'] = eda
except Exception as e:
    result['eda_summary'] = {"error": str(e)}

# Correlations
try:
    num_cols = ['FTE', 'Annual_Salary', 'Performance_Rating']
    corr_df = staff[num_cols].dropna()
    corr_result = {}
    for i in range(len(num_cols)):
        for j in range(i+1, len(num_cols)):
            c1, c2 = num_cols[i], num_cols[j]
            r = corr_df[c1].corr(corr_df[c2])
            if abs(r) >= 0.2:
                corr_result[f"{c1}__{c2}"] = round(float(r), 4)
    result['correlations'] = corr_result
except Exception as e:
    result['correlations'] = {}

# Segmentation
try:
    seg_results = []
    seg_cols = ['Department', 'Job_Level', 'Employment_Status']
    for seg in seg_cols:
        for metric in metrics:
            agg = 'mean' if metric in ['Annual_Salary', 'Performance_Rating'] else 'mean'
            grp = staff.groupby(seg)[metric].mean().dropna()
            if len(grp) > 10:
                grp = grp.nlargest(10)
            seg_results.append({
                "segment_column": seg,
                "metric_column": metric,
                "aggregation": "mean",
                "label": None,
                "results": [{"name": str(k), "value": round(float(v), 4)} for k, v in grp.items()]
            })
    # Attrition rate by Department using provided avg headcounts
    avg_hc_dept = {'Sales': 213.0, 'Operations': 118.2, 'Support': 183.2, 'Engineering': 271.1, 'Marketing': 96.6, 'Finance': 76.9, 'Legal': 6.0}
    exit_rows = staff[staff['exit_event_date'].notna()] if 'exit_event_date' in staff.columns else staff[staff['Termination_Date'].notna()]
    if 'exit_event_date' in staff.columns:
        exit_rows = staff[staff['exit_event_date'].notna()]
        dept_exits = exit_rows.groupby('Department').size()
    else:
        dept_exits = exit_rows.groupby('Department').size()
    attrition_vals = []
    for dept, avg_hc in avg_hc_dept.items():
        exits = dept_exits.get(dept, 0)
        rate = exits / avg_hc if avg_hc > 0 else 0
        attrition_vals.append({"name": dept, "value": round(float(rate), 4)})
    seg_results.append({
        "segment_column": "Department",
        "metric_column": "exit_event_date" if 'exit_event_date' in staff.columns else "Termination_Date",
        "aggregation": "ratio",
        "label": "attrition_rate",
        "results": attrition_vals
    })
    # Regrettable ratio by Department
    if 'Regrettable' in staff.columns:
        reg_grp = staff.groupby('Department').apply(lambda x: (x['Regrettable'].str.lower() == 'yes').sum() / max(len(x), 1))
        seg_results.append({
            "segment_column": "Department",
            "metric_column": "Regrettable",
            "aggregation": "ratio",
            "label": "regrettable_rate",
            "results": [{"name": str(k), "value": round(float(v), 4)} for k, v in reg_grp.items()]
        })
    result['segments'] = seg_results
except Exception as e:
    result['segments'] = [{"error": str(e)}]

# Anomalies
try:
    import numpy as np
    anomalies = []
    skip_cols = []
    for col in metrics:
        s = staff[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min())
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
            shift = 0
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo_ext = q1 - 3 * iqr
        hi_ext = q3 + 3 * iqr
        lo_4 = q1 - 4 * iqr
        hi_4 = q3 + 4 * iqr
        lo_5 = q1 - 5 * iqr
        hi_5 = q3 + 5 * iqr
        mask = (s_t < lo_ext) | (s_t > hi_ext)
        frac = mask.sum() / len(s_t)
        if frac > 0.05:
            anomalies.append({
                "column": col,
                "row_index": None,
                "value": None,
                "expected_range": f"[{float(s.quantile(0.25)):.2f}, {float(s.quantile(0.75)):.2f}]",
                "severity": "low",
                "explanation": f"{col} is heavy-tailed; extreme-value flagging skipped"
            })
            continue
        flagged = s_t[mask]
        if abs(skew) > 2:
            orig_lo = float(np.expm1(lo_ext) - shift)
            orig_hi = float(np.expm1(hi_ext) - shift)
        else:
            orig_lo = float(lo_ext)
            orig_hi = float(hi_ext)
        for idx in flagged.index[:25]:
            val_t = float(s_t[idx])
            orig_val = float(s[idx])
            if val_t > hi_5 or val_t < lo_5:
                sev = "critical"
            elif val_t > hi_4 or val_t < lo_4:
                sev = "high"
            else:
                sev = "medium"
            anomalies.append({
                "column": col,
                "row_index": int(idx),
                "value": orig_val,
                "expected_range": f"[{orig_lo:.2f}, {orig_hi:.2f}]",
                "severity": sev,
                "explanation": f"{col} value {orig_val} lies outside expected range [{orig_lo:.2f}, {orig_hi:.2f}]"
            })
        if len(anomalies) >= 25:
            break
    result['anomalies'] = anomalies[:25]
except Exception as e:
    result['anomalies'] = [{"error": str(e)}]

