# Forecasting (simple linear extrapolation of avg salary by hire cohort)
try:
    import numpy as np
    staff['Hire_Date_dt'] = pd.to_datetime(staff['Hire_Date'], errors='coerce')
    staff['hire_ym'] = staff['Hire_Date_dt'].dt.to_period('M')
    monthly_sal = staff.groupby('hire_ym')['Annual_Salary'].mean().dropna().sort_index()
    if len(monthly_sal) >= 6:
        x = np.arange(len(monthly_sal))
        y = monthly_sal.values
        coeffs = np.polyfit(x, y, 1)
        slope, intercept = coeffs[0], coeffs[1]
        last_period = monthly_sal.index[-1]
        fp = []
        for i in range(1, 4):
            next_period = last_period + i
            pred = slope * (len(monthly_sal) - 1 + i) + intercept
            fp.append({"period": str(next_period), "value": round(float(pred), 2)})
        result['forecast_points'] = fp
except Exception as e:
