# Anomalies
try:
    import numpy as np
    anomalies = []
    skip_cols = []
    for col in metrics:
        s = staff[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min())
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
            shift = 0
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo_ext = q1 - 3 * iqr
        hi_ext = q3 + 3 * iqr
        lo_4 = q1 - 4 * iqr
        hi_4 = q3 + 4 * iqr
        lo_5 = q1 - 5 * iqr
        hi_5 = q3 + 5 * iqr
        mask = (s_t < lo_ext) | (s_t > hi_ext)
        frac = mask.sum() / len(s_t)
        if frac > 0.05:
            anomalies.append({
                "column": col,
                "row_index": None,
                "value": None,
                "expected_range": f"[{float(s.quantile(0.25)):.2f}, {float(s.quantile(0.75)):.2f}]",
                "severity": "low",
                "explanation": f"{col} is heavy-tailed; extreme-value flagging skipped"
            })
            continue
        flagged = s_t[mask]
        if abs(skew) > 2:
            orig_lo = float(np.expm1(lo_ext) - shift)
            orig_hi = float(np.expm1(hi_ext) - shift)
        else:
            orig_lo = float(lo_ext)
            orig_hi = float(hi_ext)
        for idx in flagged.index[:25]:
            val_t = float(s_t[idx])
            orig_val = float(s[idx])
            if val_t > hi_5 or val_t < lo_5:
                sev = "critical"
            elif val_t > hi_4 or val_t < lo_4:
                sev = "high"
            else:
                sev = "medium"
            anomalies.append({
                "column": col,
                "row_index": int(idx),
                "value": orig_val,
                "expected_range": f"[{orig_lo:.2f}, {orig_hi:.2f}]",
                "severity": sev,
                "explanation": f"{col} value {orig_val} lies outside expected range [{orig_lo:.2f}, {orig_hi:.2f}]"
            })
        if len(anomalies) >= 25:
            break
    result['anomalies'] = anomalies[:25]
except Exception as e:
    result['anomalies'] = [{"error": str(e)}]

